package com.ferreteriahuaman.service;
import com.ferreteriahuaman.dto.SaleModels.*;import com.ferreteriahuaman.repository.*;import com.ferreteriahuaman.security.*;import com.ferreteriahuaman.security.AuthModels.Identity;import com.fasterxml.jackson.databind.ObjectMapper;import java.math.BigDecimal;import java.time.*;import java.util.*;import org.springframework.context.annotation.Profile;import org.springframework.stereotype.Service;
@Service @Profile("db") public class SaleService {
 private final SaleRepository repo;private final CashRepository cash;private final BusinessTransactions tx;private final ObjectMapper mapper;
 public SaleService(SaleRepository repo,CashRepository cash,BusinessTransactions tx,ObjectMapper mapper){this.repo=repo;this.cash=cash;this.tx=tx;this.mapper=mapper;}
 private String json(Object o){try{return mapper.writeValueAsString(o);}catch(com.fasterxml.jackson.core.JsonProcessingException e){throw new IllegalStateException("No se pudo preparar la venta");}}
 private long number(Map<String,Object> r,String k){return ((Number)r.get(k)).longValue();}
 private Map<String,Object> owned(Identity a,long id,boolean lock){var v=repo.get(id,lock).orElseThrow(()->new AuthFailure(404,"Venta no encontrada"));if(number(v,"vendedorId")!=a.id()&&!a.rol().equals("ADM"))throw new AuthFailure(403,"Solo puedes operar tus propias ventas");return v;}
 public Map<String,Object> options(){var c=cash.current();var result=new LinkedHashMap<String,Object>();result.put("fecha",c.fechaServidor());result.put("caja",c.caja()==null?null:Map.of("id",c.caja().id(),"fecha",c.caja().fecha(),"estado",c.caja().estado()));result.put("series",repo.series());result.put("datosTributariosCompletos",repo.fiscalReady());return result;}
 public List<Map<String,Object>> drafts(Identity a){return repo.drafts(a.id());}
 public Details details(Identity a,long id){return new Details(owned(a,id,false),repo.lines(id),repo.payments(id),repo.receipt(id));}
 private void version(Map<String,Object> v,LocalDateTime expected){if(!LocalDateTime.parse(v.get("version").toString()).equals(expected))throw new AuthFailure(409,"La venta cambió. Vuelve a cargarla antes de continuar");}
 public Details create(Identity a,String pc,Create i){return tx.write(a,pc,"VEN.VENDER",()->{repo.lockKey(i.clave());var previous=repo.replay("POS.CREAR",i.clave().toString(),a.id(),json(i));if(previous.isPresent())return details(a,previous.get());var current=cash.current();if(current.caja()==null||!current.caja().estado().equals("ABIERTA")||!current.caja().fecha().equals(current.fechaServidor()))throw new AuthFailure(409,"Abre la caja de hoy antes de preparar una venta");repo.lockCash(current.caja().id());var seen=new HashSet<Long>();for(var l:i.lineas())if(!seen.add(l.presentacionId()))throw new AuthFailure(400,"Agrupa las cantidades de una misma presentación en una sola línea");long id=repo.create(current.caja().id(),a.id(),i);for(var l:i.lineas())repo.add(id,l);if(repo.lines(id).size()!=i.lineas().size())throw new AuthFailure(400,"Una presentación ya no existe");repo.audit(a.id(),"POS.CREAR",id,i.clave().toString(),json(i));return details(a,id);});}
 public void validatePayments(List<Payment> payments,BigDecimal total){var seen=new HashSet<String>();BigDecimal sum=BigDecimal.ZERO;for(var p:payments){if(!seen.add(p.medio()))throw new AuthFailure(400,"Incluye cada medio de pago una sola vez");sum=sum.add(p.monto());boolean cash=p.medio().equals("EFECTIVO"),debit=p.medio().equals("DEBITO"),yape=p.medio().equals("YAPE");if(cash&&(p.recibido()==null||p.recibido().compareTo(p.monto())<0)||!cash&&p.recibido()!=null||!debit&&(p.marca()!=null||p.ultimosCuatro()!=null)||cash&&p.operacion()!=null||p.medio().equals("CREDITO")&&(payments.size()!=1||p.operacion()!=null)||yape&&(p.operacion()==null||!p.operacion().matches("[0-9]{6,20}"))||debit&&(p.operacion()==null||p.operacion().isBlank()))throw new AuthFailure(400,"Revisa los datos del medio de pago");}if(sum.compareTo(total)!=0)throw new AuthFailure(400,"Los pagos deben cubrir exactamente el total de la venta");}
 public Details confirm(Identity a,String pc,long id,Confirm i){return tx.write(a,pc,"VEN.VENDER",()->{var v=owned(a,id,false);repo.lockCash(number(v,"cajaId"));v=owned(a,id,true);String key=v.get("clave").toString();var previous=repo.replay("POS.CONFIRMAR","POS_CONFIRM:"+key,a.id(),json(i));if(previous.isPresent())return details(a,id);version(v,i.version());if(!v.get("estado").equals("BORRADOR"))throw new AuthFailure(409,"La venta no es un borrador activo");validatePayments(i.pagos(),new BigDecimal(v.get("total").toString()));for(var p:i.pagos())repo.payment(id,p);var assignments=new ArrayList<Map<String,Object>>();for(var s:i.asignaciones())assignments.add(Map.of("id_detalle_venta",s.lineaId(),"id_unidad_existencia",s.unidadId(),"numero_pieza",s.pieza(),"cantidad_base",s.cantidad()));repo.confirm(id,i.serieId(),UUID.fromString(key),json(assignments));repo.audit(a.id(),"POS.CONFIRMAR",id,"POS_CONFIRM:"+key,json(i));return details(a,id);});}
 public Details discard(Identity a,String pc,long id,Discard i){return tx.write(a,pc,"VEN.VENDER",()->{var v=owned(a,id,false);repo.lockCash(number(v,"cajaId"));v=owned(a,id,true);if(!v.get("estado").equals("DESCARTADA"))version(v,i.version());repo.discard(id,i);return details(a,id);});}
 public com.ferreteriahuaman.dto.CatalogModels.Page<Map<String,Object>> units(Identity a,long id,long line,int page){owned(a,id,false);if(page<0||page>1000000)throw new AuthFailure(400,"Revisa la página");return repo.units(id,line,page);}
}
